//! Fixture-driven subtitle demux tests. Each test loads a fixture
//! generated by the `subtitles/regen.sh` regenerator and asserts
//! classification + Sample-event emission.

use std::path::PathBuf;
use std::process::Command;

use crate::common::mux_demux::demux_bytes_flushed as collect_events;
use tst_core::mpegts::demux::{DemuxEvent, SamplePayload, StreamKind, SubtitleCodec};

fn load(name: &str) -> Vec<u8> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/subtitles")
        .join(name);
    std::fs::read(&path).unwrap_or_else(|e| panic!("read fixture {}: {}", path.display(), e))
}

fn ffprobe_available() -> bool {
    Command::new("ffprobe")
        .arg("-version")
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
}

#[test]
fn dvb_subtitling_eng_classifies_as_dvb_subtitling() {
    let bytes = load("dvb_subtitling_eng.ts");
    let events = collect_events(&bytes);
    assert!(
        events.iter().any(|e| matches!(
            e,
            DemuxEvent::Sample {
                payload: SamplePayload::Subtitle {
                    codec: SubtitleCodec::DvbSubtitling,
                    ..
                },
                ..
            }
        )),
        "expected DvbSubtitling Sample event, got {events:?}"
    );
}

#[test]
fn dvb_subtitling_multi_lang_yields_two_streams() {
    let bytes = load("dvb_subtitling_multi_lang.ts");
    let events = collect_events(&bytes);
    let pm = events
        .iter()
        .find_map(|e| match e {
            DemuxEvent::ProgramMap(pm) => Some(pm),
            _ => None,
        })
        .expect("ProgramMap event");
    let sub_count = pm
        .streams
        .iter()
        .filter(|s| matches!(s.kind, StreamKind::Subtitle(SubtitleCodec::DvbSubtitling)))
        .count();
    assert_eq!(
        sub_count, 2,
        "expected two DvbSubtitling streams in ProgramMap, got {sub_count}"
    );
}

