#[test]
fn webvtt_simple_classifies_as_webvtt_in_ts() {
    let bytes = load("webvtt_in_ts_simple.ts");
    let events = collect_events(&bytes);
    let payload = events
        .iter()
        .find_map(|e| match e {
            DemuxEvent::Sample {
                payload:
                    SamplePayload::Subtitle {
                        codec: SubtitleCodec::WebVttInTs,
                        payload,
                    },
                ..
            } => Some(payload.clone()),
            _ => None,
        })
        .expect("WebVTT Sample event");
    assert!(
        payload.windows(6).any(|w| w == b"WEBVTT"),
        "expected WEBVTT signature in payload, got {} bytes",
        payload.len()
    );
}

#[test]
fn webvtt_multi_cue_yields_multiple_sample_events() {
    let bytes = load("webvtt_in_ts_multi_cue.ts");
    let events = collect_events(&bytes);
    let cues = events
        .iter()
        .filter(|e| {
            matches!(
                e,
                DemuxEvent::Sample {
                    payload: SamplePayload::Subtitle {
                        codec: SubtitleCodec::WebVttInTs,
                        ..
                    },
                    ..
                }
            )
        })
        .count();
    assert!(cues >= 5, "expected >= 5 WebVTT Sample events, got {cues}");
}

