#[test]
fn subtitle_with_klv_same_program_yields_both_kinds() {
    let bytes = load("subtitle_with_klv_same_program.ts");
    let events = collect_events(&bytes);
    let has_subtitle = events.iter().any(|e| {
        matches!(
            e,
            DemuxEvent::Sample {
                payload: SamplePayload::Subtitle { .. },
                ..
            }
        )
    });
    let has_klv = events
        .iter()
        .any(|e| matches!(e, DemuxEvent::Metadata { .. }));
    assert!(has_subtitle, "expected subtitle Sample event");
    assert!(has_klv, "expected KLV Metadata event");
}

#[test]
fn webvtt_multi_program_with_klv_yields_two_program_maps() {
    let bytes = load("webvtt_multi_program_with_klv.ts");
    let events = collect_events(&bytes);
    let pms: Vec<_> = events
        .iter()
        .filter_map(|e| match e {
            DemuxEvent::ProgramMap(pm) => Some(pm),
            _ => None,
        })
        .collect();
    assert_eq!(
        pms.len(),
        2,
        "expected 2 ProgramMap events, got {}",
        pms.len()
    );
}

#[test]
#[ignore = "ffprobe-only — runs locally, gated on ffprobe presence"]
fn dvb_subtitling_ffprobe_agrees() {
    if !ffprobe_available() {
        eprintln!("skipping: ffprobe not on PATH");
        return;
    }
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/subtitles/dvb_subtitling_eng.ts");
    let out = Command::new("ffprobe")
        .args([
            "-v",
            "error",
            "-show_entries",
            "stream=codec_name,codec_type",
            "-of",
            "csv=p=0",
        ])
        .arg(&path)
        .output()
        .expect("run ffprobe");
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(stdout.contains("dvb_subtitle"), "ffprobe output: {stdout}");
}

