#[test]
#[ignore = "ffprobe-only"]
fn webvtt_in_ts_ffprobe_agrees() {
    if !ffprobe_available() {
        eprintln!("skipping: ffprobe not on PATH");
        return;
    }
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/subtitles/webvtt_in_ts_simple.ts");
    let out = Command::new("ffprobe")
        .args([
            "-v",
            "error",
            "-show_entries",
            "stream=codec_name",
            "-of",
            "csv=p=0",
        ])
        .arg(&path)
        .output()
        .expect("run ffprobe");
    let stdout = String::from_utf8_lossy(&out.stdout);
    // ffmpeg's labels for WebVTT-in-TS have drifted across releases —
    // some builds report "webvtt", others fall back to the generic
    // "bin_data" since the WebVTT-in-MPEG-TS path (per Apple HLS) is
    // not on every ffmpeg's well-known-codec list. We accept any of
    // the plausible labels; the round-trip mux+demux test already
    // proves the codec is classified correctly inside our crate.
    assert!(
        stdout.contains("webvtt") || stdout.contains("subtitle") || stdout.contains("bin_data"),
        "ffprobe output: {stdout}"
    );
}
